<div class='col-start-1 col-end-1 row-start-1 row-end-1 w-full transition duration-300' x-show='currentStep === 5' x-cloak><h2 class='mb-5 text-center text-[24px] font-medium leading-[1.2em]'><span class='block text-[0.875em] opacity-50'>Add quoting intelligence</span>Should AI help tighten the quote?</h2><label class='mb-4 flex items-center justify-between rounded-[10px] bg-foreground/5 px-6 py-4 text-sm font-medium'><span>Enable AI assisted quoting</span><input type='checkbox' x-model='formData.quote_ai_enabled'></label><div class='rounded-[10px] bg-foreground/5 px-6 py-3'><label class='mb-2 block text-2xs opacity-50'>Missing-info questions (one per line)</label><textarea class='w-full border-none bg-transparent text-sm font-medium min-h-[150px]' :disabled='!formData.quote_ai_enabled' x-model='formData.ai_questionsText' x-init="formData.ai_questionsText = formData.ai_questions.join('\n')" @input="formData.ai_questions = ($event.target.value || '').split('\n').map(v => v.trim()).filter(Boolean)"></textarea></div><div class='mt-4 rounded-[10px] bg-foreground/5 px-6 py-3'><label class='mb-2 block text-2xs opacity-50'>Attach quote bot</label><div class='mb-3 flex items-center gap-3 text-sm'><input type='checkbox' x-model='formData.attach_quote_bot'> <span>Attach a quote bot to follow up and handle acceptance actions</span></div><input class='w-full border-none bg-transparent text-sm font-medium' type='text' x-model='formData.quote_bot_name' placeholder='Quote Concierge Bot'></div><div class='mt-3 text-xs text-red-500' x-show='stepsErrors.get(5)?.length'><template x-for='error in stepsErrors.get(5)' :key='error'><div x-text='error'></div></template></div><x-button class='mt-5 w-full bg-gradient-to-r from-gradient-from via-gradient-via to-gradient-to py-[18px] text-xs font-medium leading-none text-primary-foreground' @click.prevent='nextStep()'>Continue <x-tabler-arrow-right class='size-4' /></x-button></div>